# Builds site/data/tracks/19-spc.js: runs every step of steps19.py in order, as one Python file,
# with the OEE track's v_hourly_barrels view created from that lesson's own code,
# against the canonical sample database on SQL Server (BC_SQL_PASSWORD and the container from
# sql_exec.py), and records what each step prints as its output. Do not edit the JS file by hand.
#   python3 build19.py            write the track
#   python3 build19.py --check    report a difference, change nothing
import contextlib, io, json, os, re, shutil, subprocess, sys, tempfile, warnings
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
sys.path.insert(0, str(HERE))
sys.path.insert(0, str(HERE.parent / "lib" / "pydb"))
import plantdb
from steps19 import CODE
from lessons19 import TRACK, LESSONS

def lesson_code(track_file, title):
    js = ("const fs=require('fs'),vm=require('vm'),c={};c.BC={addLanguage(){},addGlossary(){},addLane(){},addTrack(t){c.t=t}};"
          "vm.createContext(c);vm.runInContext(fs.readFileSync(process.argv[1],'utf8'),c);"
          "console.log(JSON.stringify(c.t.lessons.find(l=>l.t===process.argv[2]).code))")
    return json.loads(subprocess.run(["node", "-e", js, str(ROOT / "site/data/tracks" / track_file), title], capture_output=True, text=True, check=True).stdout)

plantdb.reset([lesson_code("03-oee.js", "Hourly barrels view")])
plantdb.use_real_database()
warnings.filterwarnings("ignore", message="pandas only supports SQLAlchemy")
assert [t for t, *_ in LESSONS] == list(CODE), "lessons19.py and steps19.py list different steps"

outs, g = {}, {}
with tempfile.TemporaryDirectory() as d:
    os.chdir(d)  # the workbook steps save an .xlsx
    for title, *_ in LESSONS:
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            exec(CODE[title], g)
        outs[title] = buf.getvalue().rstrip()

# Cross-check the SPC arithmetic a second way, in plain SQL on the same database: the center line,
# R-bar (all 21 subgroups) and p-bar must match what the Python steps computed.
cur = g["conn"].cursor()
cur.execute("""WITH s AS (SELECT DATEDIFF(MINUTE, '2026-10-31 06:00', sample_ts) / 480 AS k,
                  AVG(CAST(depth_mm AS FLOAT)) AS xbar, CAST(MAX(depth_mm) - MIN(depth_mm) AS FLOAT) AS r
               FROM char_depth WHERE sample_ts >= '2026-10-31 06:00' AND sample_ts < '2026-11-07 06:00'
               GROUP BY DATEDIFF(MINUTE, '2026-10-31 06:00', sample_ts) / 480)
               SELECT AVG(xbar), AVG(r) FROM s""")
center, rbar = cur.fetchone()
cur.execute("""SELECT CAST((SELECT SUM(qty) FROM reject_log WHERE machine = 'Char Station 2'
                  AND ts >= '2026-10-31 06:00' AND ts < '2026-11-07 06:00') AS FLOAT)
               / (SELECT SUM(made_this_hour) FROM v_hourly_barrels WHERE machine = 'Char Station 2'
                  AND ts > '2026-10-31 06:00' AND ts <= '2026-11-07 06:00')""")
p_bar = cur.fetchone()[0]
for name, sql_v, py_v in [("center", center, g["lim"]["center"]), ("R-bar", rbar, g["lim"]["rbar"]), ("p-bar", p_bar, g["p_bar"])]:
    if abs(sql_v - py_v) > 1e-9:
        sys.exit(f"SQL cross-check failed: {name} is {sql_v} in SQL, {py_v} in Python")
print("SQL cross-check: center, R-bar and p-bar match")

def whole(k, code):
    pre = r"(?<!\w)" if re.match(r"\w", k) else ""
    post = r"(?!\w)" if re.search(r"\w$", k) else ""
    return re.search(pre + re.escape(k) + post, code) is not None

tpl = lambda x: "`" + x.replace("\\", "\\\\").replace("`", "\\`").replace("${", "\\${") + "`"
js = lambda v: json.dumps(v, ensure_ascii=False)
lines = ["// Project track 19: SPC and Control Charts (Python on the plant database)",
         "// Generated by tools/output-checks/track19-spc/build19.py from steps19.py and lessons19.py. Do not edit by hand.",
         "BC.addTrack({", f"  id: {js(TRACK['id'])},", f"  name: {js(TRACK['name'])},", f"  sub: {js(TRACK['sub'])},", "  lessons: ["]
for title, goal, about, terms in LESSONS:
    code = CODE[title]
    for k, *_ in terms:
        if k is not None and not whole(k, code):
            sys.exit(f"{title}: term key {k!r} is not in the code")
    lines += ["    {", '      lang: "python",', f"      file: {js(TRACK['file'])},", f"      t: {js(title)},", f"      goal: {js(goal)},",
              f"      code: {tpl(code)},", f"      about: {js(about)},", "      terms: ["]
    lines += [f"        [{'null' if k is None else js(k)}, {js(a)}, {js(b)}]," for k, a, b in terms]
    lines += ["      ],", f"      out: {tpl(outs[title])},", "    },"]
lines += ["  ],", "});", ""]
text = "\n".join(lines)
target = ROOT / "site/data/tracks/19-spc.js"
if "--check" in sys.argv:
    same = target.exists() and target.read_text() == text
    print("19-spc.js is current" if same else "19-spc.js is stale: run python3 build19.py")
    sys.exit(0 if same else 1)
target.write_text(text)
print(f"wrote {target.relative_to(ROOT)}: {len(LESSONS)} steps")
